import Synchronization

struct LogSettings: Sendable {
    private static let level = Mutex(1)        // Swift 6, thread-safe

    var current: Int {
        get { Self.level.withLock { $0 } }
        set { Self.level.withLock { $0 = newValue } }
    }
}
